package br.edu.scoa.academico.infraestrutura.persistencia;
import br.edu.scoa.academico.aplicacao.matriculas.*;import br.edu.scoa.academico.dominio.matriculas.*;import java.sql.*;import java.time.*;import java.util.*;
public final class RepositorioInscricoesMysql implements RepositorioInscricoes {private final ConfiguracaoBanco banco;public RepositorioInscricoesMysql(ConfiguracaoBanco b){banco=b;}public InscricaoTurma inscrever(InscricaoTurma i,UUID op,long autor,Instant instante){try(var c=banco.abrir()){c.setAutoCommit(false);try{long vagas;try(var s=c.prepareStatement("SELECT capacidade FROM turma WHERE id=? AND situacao='ABERTA' FOR UPDATE")){s.setLong(1,i.turmaId());try(var r=s.executeQuery()){if(!r.next())throw new FalhaMatricula(FalhaMatricula.Codigo.TURMA_NAO_ABERTA);vagas=r.getLong(1);}}try(var s=c.prepareStatement("SELECT COUNT(*) FROM inscricao_turma WHERE turma_id=? AND situacao='ATIVA' FOR UPDATE")){s.setLong(1,i.turmaId());try(var r=s.executeQuery()){r.next();if(r.getLong(1)>=vagas)throw new FalhaMatricula(FalhaMatricula.Codigo.VAGA_INDISPONIVEL);}}try(var s=c.prepareStatement("SELECT id FROM inscricao_turma WHERE matricula_id=? AND turma_id=? AND situacao='ATIVA' FOR UPDATE")){s.setLong(1,i.matriculaId());s.setLong(2,i.turmaId());try(var r=s.executeQuery()){if(r.next())throw new FalhaMatricula(FalhaMatricula.Codigo.DUPLICIDADE);}}try(var s=c.prepareStatement("INSERT INTO inscricao_turma(matricula_id,turma_id,situacao,inscrita_em,versao_registro,operacao_criacao) VALUES(?,?,?, ?,1,?)",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,i.matriculaId());s.setLong(2,i.turmaId());s.setString(3,"ATIVA");s.setTimestamp(4,Timestamp.from(i.inscritaEm()));s.setString(5,op.toString());s.executeUpdate();try(var r=s.getGeneratedKeys()){r.next();c.commit();return i.identificado(r.getLong(1),1);}}}catch(Exception e){c.rollback();if(e instanceof FalhaMatricula f)throw f;throw new FalhaMatricula(FalhaMatricula.Codigo.INSCRICAO_INVALIDA);}}catch(SQLException e){throw new FalhaMatricula(FalhaMatricula.Codigo.INSCRICAO_INVALIDA);}}public InscricaoTurma cancelar(InscricaoTurma i,UUID op,long autor,Instant instante){throw new UnsupportedOperationException("Cancelamento será integrado na próxima etapa do ACA-04.");}public List<InscricaoTurma> ativasPorMatricula(long matricula){return List.of();}}
